const { expect } = require("chai");
const { ethers } = require("hardhat");
const fs = require("fs");
const path = require("path");

// R4.5 — QLSAVerifierRecursive: one on-chain call that (1) replays the inner
// VFRI11 Fiat-Shamir channel from public roots (challenges become
// channel-derived public inputs) and (2) verifies the OUTER recursive-trace
// VFRI11 proof cross-bound to those inner publics. Fixture generated by
// `cargo test write_recursive_e2e_fixture -- --ignored` in stark_stwo.
describe("QLSAVerifierRecursive — recursive proof on-chain entry point (R4.5)", function () {
  let recursive;
  let fx;
  let innerTuple;

  before(async function () {
    const VFRI11 = await ethers.getContractFactory("QLSAVerifierVFRI11");
    const vfri11 = await VFRI11.deploy();
    await vfri11.waitForDeployment();

    const Recursive = await ethers.getContractFactory("QLSAVerifierRecursive");
    recursive = await Recursive.deploy(await vfri11.getAddress());
    await recursive.waitForDeployment();

    fx = JSON.parse(
      fs.readFileSync(path.join(__dirname, "fixtures", "recursive_e2e.json"), "utf8")
    );
    innerTuple = {
      traceRoot: fx.inner.traceRoot,
      oodsComboPos: fx.inner.oodsComboPos,
      oodsComboNeg: fx.inner.oodsComboNeg,
      compRoot: fx.inner.compRoot,
      friLayerRoots: fx.inner.friLayerRoots,
      batchRoot: fx.inner.batchRoot,
      treeDepth: fx.inner.treeDepth,
      nQueries: fx.inner.nQueries,
    };
  });

  it("outerBindingRoot matches the Rust keccak binding", async function () {
    const bound = await recursive.outerBindingRoot(
      fx.inner.traceRoot,
      fx.inner.friLayerRoots[fx.inner.friLayerRoots.length - 1]
    );
    expect(bound).to.equal(fx.outer.bindingRoot);
  });

  it("verifies the honest recursive bundle and returns the replayed challenges", async function () {
    const [ok, ch] = await recursive.verifyRecursive(
      innerTuple,
      fx.outer.proof,
      fx.outer.commitment,
      fx.outer.hints
    );
    expect(ok).to.equal(true, "outer proof must verify against the inner-bound root");
    expect(ch.zX.toString()).to.equal(fx.expected.zX, "replayed zX");
    expect(ch.queryIndices.length).to.equal(fx.expected.queryIndices.length);
    for (let i = 0; i < ch.queryIndices.length; i++) {
      expect(ch.queryIndices[i].toString()).to.equal(fx.expected.queryIndices[i]);
    }
  });

  it("rejects when the inner publics are tampered (binding root shifts)", async function () {
    const tampered = {
      ...innerTuple,
      traceRoot: "0x" + (BigInt(fx.inner.traceRoot) ^ 1n).toString(16).padStart(64, "0"),
    };
    const [ok, ch] = await recursive.verifyRecursive(
      tampered,
      fx.outer.proof,
      fx.outer.commitment,
      fx.outer.hints
    );
    expect(ok).to.equal(false, "outer proof must not verify for different inner publics");
    // And the replayed challenges shift too (full-root absorption).
    expect(ch.zX.toString()).to.not.equal(fx.expected.zX);
  });

  it("rejects tampered outer hints", async function () {
    const bytes = ethers.getBytes(fx.outer.hints);
    bytes[bytes.length - 40] ^= 0xff;
    const [ok] = await recursive.verifyRecursive(
      innerTuple,
      fx.outer.proof,
      fx.outer.commitment,
      ethers.hexlify(bytes)
    );
    expect(ok).to.equal(false, "tampered outer hints must not verify");
  });

  it("rejects a wrong outer commitment", async function () {
    const bad = "0x" + (BigInt(fx.outer.commitment) ^ 1n).toString(16).padStart(32, "0");
    const [ok] = await recursive.verifyRecursive(
      innerTuple,
      fx.outer.proof,
      bad,
      fx.outer.hints
    );
    expect(ok).to.equal(false, "wrong outer commitment must not verify");
  });
});
